 44→// loadCapture 读出所有场景的所有帧。
 45→func loadCapture(t *testing.T) []captureFrame {
 46→	t.Helper()
 47→	scenarios, err := os.ReadDir(captureRoot)
 48→	if err != nil {
 49→		t.Fatalf("读 %s: %v（fixture 应当随代码一起提交）", captureRoot, err)
