181→		checked, checked-exempted-len(bad), exempted, skipped)
182→	if len(bad) > 0 {
183→		t.Logf("失败分布: %v", bad)
184→	}
185→	if checked < 100 {
186→		t.Fatalf("只比对了 %d 条消息，样本太少，fixture 可能没采全", checked)
187→	}
