190→// isErrorStatus 判断该 NTSTATUS 是否意味着「响应体是 ERROR_RESPONSE」。
191→//
192→// MS-SMB2 §2.2.2：出错时服务端返回 ERROR_RESPONSE。有几个坑：
193→//   - STATUS_MORE_PROCESSING_REQUIRED (0xC0000016)：NTLM 第二段，
194→//     带**完整的** SESSION_SETUP Response，不是 ERROR_RESPONSE；
195→//   - STATUS_BUFFER_OVERFLOW (0x80000005)：READ/IOCTL 部分数据，带正常体；
196→//   - STATUS_PENDING (0x00000103)：严重级是 SUCCESS，看着像成功，
197→//     但它是**异步中间响应**（MS-SMB2 §3.3.4.2），体是 9 字节的 ERROR_RESPONSE，
198→//     头里带 SMB2_FLAGS_ASYNC_COMMAND + AsyncId。
199→//     抓包为证：testdata/capture/tree-connect/012-s2c-IOCTL.bin。
200→func isErrorStatus(status uint32) bool {
201→	switch status {
202→	case 0x00000000, 0xC0000016, 0x80000005:
203→		return false
204→	case 0x00000103: // STATUS_PENDING：异步中间响应，体是 ERROR_RESPONSE
205→		return true
206→	}
207→	// 其余：只有 ERROR/WARNING 级（最高位置位）才是错误。
208→	return status&0x80000000 != 0
209→}
