488→// splitChain 把复合链拆成一条条独立消息。
489→//
490→// 链中每条消息的 NextCommand 是**相对本条消息头起点**的偏移；最后一条为 0，
491→// 其后的字节属于最后一条（可能有尾部对齐填充）。
492→func splitChain(t *testing.T, f captureFrame) [][]byte {
493→	t.Helper()
494→	var out [][]byte
495→	b := f.data
496→	for i := 0; ; i++ {
497→		if len(b) < HeaderSize {
498→			t.Errorf("%s: 复合链第 %d 条不足 64 字节", f, i)
499→			return out
500→		}
501→		next := int(binary.LittleEndian.Uint32(b[0x14:]))
502→		if next == 0 {
503→			out = append(out, b)
504→			return out
505→		}
506→		if next < HeaderSize || next > len(b) {
507→			t.Errorf("%s: 复合链第 %d 条 NextCommand=%d 越界（总长 %d）", f, i, next, len(b))
508→			return out
509→		}
510→		out = append(out, b[:next])
511→		b = b[next:]
512→		if i > 64 {
513→			t.Errorf("%s: 复合链过长，疑似成环", f)
514→			return out
515→		}
516→	}
517→}
