  1→package wire
  2→
  3→// 真实 Samba 抓包比对（AGENTS.md §3「关键路径要有抓包比对」）。
  4→//
  5→// 为什么需要这个：其余单测都是「自己编码 → 自己解码 → 对得上」，
  6→// 这只能证明 wire 包**自洽**，证明不了真实客户端/服务器能看懂我们的字节。
  7→// 这里的 fixture 是把真实 smbclient / go-smb2 与真实 smbd 之间的流量
  8→// 逐帧转储下来的（采集方式见 test/capture/proxy.go 与 test/capture/capture.sh），
  9→// 于是可以做两件单测做不到的事：
 10→//
 11→//	方向一（解析）：真实客户端请求 → ParseXxxRequest 必须成功，字段值合理。
 12→//	方向二（编码）：真实 smbd 响应 → Parse → Append → **必须逐字节等于原始报文**。
 13→//
 14→// 方向二是强约束：它等价于「给定同样的字段值，我们编出来的字节和 Samba
 15→// 一模一样」，比手工挑几个字段 diff 严格得多，而且不需要伪造 ServerGuid、
 16→// SystemTime 这类服务端私有值 —— 它们从真实报文里解析出来后原样写回。
 17→// 真正对不上的地方在 exemptions 里逐条列出并说明原因。
 18→//
 19→// 本测试**不需要**本机装 samba：fixture 已经提交进仓库。
 20→
 21→import (
 22→	"bytes"
 23→	"encoding/binary"
 24→	"fmt"
 25→	"os"
 26→	"path/filepath"
 27→	"sort"
 28→	"strings"
 29→	"testing"
 30→)
 31→
 32→const captureRoot = "testdata/capture"
 33→
 34→// captureFrame 是一帧抓包。Data 是去掉 4 字节 Direct TCP 长度前缀之后的报文体。
 35→type captureFrame struct {
 36→	scenario string
 37→	file     string // 形如 002-s2c-NEGOTIATE.bin
 38→	response bool   // 由文件名里的 s2c 决定，仅用于挑选，不参与断言
 39→	data     []byte
 40→}
 41→
 42→func (f captureFrame) String() string { return f.scenario + "/" + f.file }
 43→
 44→// loadCapture 读出所有场景的所有帧。
 45→func loadCapture(t *testing.T) []captureFrame {
 46→	t.Helper()
 47→	scenarios, err := os.ReadDir(captureRoot)
 48→	if err != nil {
 49→		t.Fatalf("读 %s: %v（fixture 应当随代码一起提交）", captureRoot, err)
 50→	}
 51→	var frames []captureFrame
 52→	for _, s := range scenarios {
 53→		if !s.IsDir() {
 54→			continue
 55→		}
 56→		dir := filepath.Join(captureRoot, s.Name())
 57→		ents, err := os.ReadDir(dir)
 58→		if err != nil {
 59→			t.Fatalf("读 %s: %v", dir, err)
 60→		}
 61→		names := make([]string, 0, len(ents))
 62→		for _, e := range ents {
 63→			if strings.HasSuffix(e.Name(), ".bin") {
 64→				names = append(names, e.Name())
 65→			}
 66→		}
 67→		sort.Strings(names)
 68→		for _, n := range names {
 69→			b, err := os.ReadFile(filepath.Join(dir, n))
 70→			if err != nil {
 71→				t.Fatalf("读 %s: %v", n, err)
 72→			}
 73→			frames = append(frames, captureFrame{
 74→				scenario: s.Name(),
 75→				file:     n,
 76→				response: strings.Contains(n, "-s2c-"),
 77→				data:     b,
 78→			})
 79→		}
 80→	}
 81→	if len(frames) == 0 {
 82→		t.Fatalf("%s 下一帧都没有", captureRoot)
 83→	}
 84→	return frames
 85→}
 86→
 87→// TestCaptureFixturesSane 先确认 fixture 本身没坏：要么是 SMB2 报文，
 88→// 要么是 SMB3 加密报文（TRANSFORM，wire 层不负责解密）。
 89→func TestCaptureFixturesSane(t *testing.T) {
 90→	frames := loadCapture(t)
 91→	var smb2, transform int
 92→	for _, f := range frames {
 93→		switch {
 94→		case IsTransform(f.data):
 95→			transform++
 96→			if !strings.Contains(f.file, "TRANSFORM") {
 97→				t.Errorf("%s: 内容是 TRANSFORM 但文件名不是", f)
 98→			}
 99→		case IsSMB2(f.data):
100→			smb2++
101→			if _, err := ParseHeader(f.data); err != nil {
102→				t.Errorf("%s: ParseHeader: %v", f, err)
103→			}
104→		default:
105→			t.Errorf("%s: 既不是 SMB2 也不是 TRANSFORM，前 4 字节 % X", f, f.data[:min(4, len(f.data))])
106→		}
107→	}
108→	t.Logf("共 %d 帧：SMB2 明文 %d，SMB3 加密 %d", len(frames), smb2, transform)
109→	if smb2 == 0 {
110→		t.Fatal("没有任何明文 SMB2 帧，fixture 采集姿势不对")
111→	}
112→}
113→
114→// TestCaptureHeaderRoundTrip 单独验证头：ParseHeader → Append 必须逐字节还原。
115→// 头是所有报文共用的，先把它钉死，后面的体比对才有意义。
116→func TestCaptureHeaderRoundTrip(t *testing.T) {
117→	for _, f := range loadCapture(t) {
118→		if !IsSMB2(f.data) {
119→			continue
120→		}
121→		for _, m := range splitChain(t, f) {
122→			h, err := ParseHeader(m)
123→			if err != nil {
124→				t.Errorf("%s: ParseHeader: %v", f, err)
125→				continue
126→			}
127→			if got := h.Append(nil); !bytes.Equal(got, m[:HeaderSize]) {
128→				t.Errorf("%s: 头 round-trip 不一致\n%s", f, hexDiff(m[:HeaderSize], got))
129→			}
130→		}
131→	}
132→}
