134→// TestCaptureBodyRoundTrip 是核心用例：
135→// 真实报文 → Parse → Append → 必须逐字节等于原始报文。
136→func TestCaptureBodyRoundTrip(t *testing.T) {
137→	var checked, skipped, exempted int
138→	bad := map[string]int{}
139→
140→	for _, f := range loadCapture(t) {
141→		if !IsSMB2(f.data) {
142→			continue
143→		}
144→		for _, m := range splitChain(t, f) {
145→			h, err := ParseHeader(m)
146→			if err != nil {
