152→			// STATUS_MORE_PROCESSING_REQUIRED / STATUS_BUFFER_OVERFLOW 例外：
153→			// 它们仍然带正常的命令响应体。
154→			isErr := h.IsResponse() && isErrorStatus(h.Status)
