211→// exempt 是**显式豁免清单**：列出我们与真实实现故意不一致、且确认无害的地方。
212→// want 是真实字节，got 是我们重新编码出来的。返回非空字符串表示豁免，内容是原因。
213→//
214→// 加新条目的门槛：必须先确认「不一致的是对端可以忽略的填充/冗余字节」，
215→// 而不是「我们算错了偏移或长度」。有疑问一律当成我们错（AGENTS.md §9）。
216→func exempt(h Header, want, got []byte) string {
217→	// —— 豁免 1：ERROR Response 的 ErrorData 占位字节内容未定义 ——
218→	//
219→	// MS-SMB2 §2.2.2 只要求「ByteCount 为 0 时 ErrorData 仍占 1 字节」，
220→	// 没规定这个字节的值。Samba 会把上一次用过的缓冲区残留写出去
221→	// （抓包里见过 0x21），我们写 0。对端按 ByteCount=0 处理，不会读它。
222→	// 例：testdata/capture/tree-connect/012-s2c-IOCTL.bin（STATUS_PENDING 中间响应）。
223→	if h.IsResponse() && len(want) == HeaderSize+9 && len(got) == len(want) &&
224→		bytes.Equal(want[:len(want)-1], got[:len(got)-1]) {
225→		return fmt.Sprintf("ERROR Response 占位字节：真实 0x%02X，我们 0x%02X（MS-SMB2 §2.2.2 未定义其值）",
226→			want[len(want)-1], got[len(got)-1])
227→	}
228→
229→	// —— 豁免 2：smbclient 在 CREATE Request 文件名后多发一个 UTF-16 NUL ——
230→	//
231→	// NameLength 不包含这 2 字节，服务端按 NameLength 取名字，多出来的被忽略。
232→	// 这是 smbclient 的习惯，同一份抓包里的 go-smb2 客户端就不发
233→	// （testdata/capture/gosmb2/017-c2s-CREATE.bin 能逐字节对上）。
234→	// 我们作为服务端不需要复刻客户端的习惯。
235→	if !h.IsResponse() && h.Command == CommandCreate &&
236→		len(want) == len(got)+2 && bytes.Equal(want[:len(got)], got) &&
237→		want[len(want)-2] == 0 && want[len(want)-1] == 0 {
238→		return "smbclient 在 CREATE Request 文件名后多发 2 字节 UTF-16 NUL（不计入 NameLength）"
239→	}
240→
241→	return ""
242→}
