523→// hexDiff 打印两段字节的差异，只展示第一处不同附近的窗口，避免刷屏。
524→func hexDiff(want, got []byte) string {
525→	var sb strings.Builder
526→	fmt.Fprintf(&sb, "  长度: 真实=%d 我们=%d\n", len(want), len(got))
527→	at := -1
528→	for i := 0; i < len(want) && i < len(got); i++ {
529→		if want[i] != got[i] {
530→			at = i
531→			break
532→		}
533→	}
534→	if at < 0 {
535→		if len(want) == len(got) {
536→			return sb.String() + "  （内容相同）\n"
537→		}
538→		at = min(len(want), len(got))
539→	}
540→	fmt.Fprintf(&sb, "  首个不同字节在偏移 %d (0x%X)", at, at)
541→	if at >= HeaderSize {
542→		fmt.Fprintf(&sb, "，即报文体内偏移 %d", at-HeaderSize)
543→	}
544→	sb.WriteByte('\n')
545→
546→	lo := max(0, at-16)
547→	hi := min(max(len(want), len(got)), at+48)
548→	sb.WriteString("  真实: " + hexWindow(want, lo, hi) + "\n")
549→	sb.WriteString("  我们: " + hexWindow(got, lo, hi) + "\n")
550→	return sb.String()
551→}
552→
553→func hexWindow(b []byte, lo, hi int) string {
554→	if lo > len(b) {
555→		return "(超出末尾)"
556→	}
557→	hi = min(hi, len(b))
558→	var sb strings.Builder
559→	fmt.Fprintf(&sb, "[%d..%d]", lo, hi)
560→	for i := lo; i < hi; i++ {
561→		fmt.Fprintf(&sb, " %02X", b[i])
562→	}
563→	return sb.String()
564→}
